/**
 * recommendedAllocation — DETERMINISTIC (non-AI) risk-based target allocation for
 * the real connected wallet, implementing the APPROVED MVP product rule in
 * rules/financial-logic-boundaries.md ("Recommended Allocation (real connected
 * wallet — APPROVED MVP)").
 *
 * This is the "deterministic product logic" the allocation boundary requires: the
 * target mix is NOT invented by the chart/UI and NOT generated by Smith AI — it is
 * a fixed, bucket-level (Crypto / Stables) mapping from the saved risk level,
 * applied to the user's CURRENT total priced USD value (tokenPrices.ts). Two
 * buckets only. Unpriced / unknown assets are already excluded upstream (they are
 * not in totalPricedUsd), so they are never classified into a target bucket.
 *
 * No fixture/demo value is used, no price is invented, no per-token target is
 * produced (per-token targets remain out of scope per the boundary doc).
 */

/** Approved bucket-level target by risk level (percent of priced value). */
export const RISK_TARGET_ALLOCATION: Record<
  string,
  { cryptoPct: number; stablePct: number }
> = {
  very_low: { cryptoPct: 20, stablePct: 80 },
  low: { cryptoPct: 40, stablePct: 60 },
  medium: { cryptoPct: 60, stablePct: 40 },
  high: { cryptoPct: 80, stablePct: 20 },
  very_high: { cryptoPct: 90, stablePct: 10 },
};

export interface RecommendedAllocation {
  cryptoPct: number;
  stablePct: number;
  cryptoUsd: number;
  stableUsd: number;
}

/**
 * Risk-based target allocation applied to the current total priced USD value.
 * Returns null (recommended unavailable) when there is no saved risk level or no
 * priced value to size the target against. Never throws, never invents a value.
 */
export function deriveRecommendedAllocation(inputs: {
  riskTolerance: string | undefined;
  totalPricedUsd: number | null;
}): RecommendedAllocation | null {
  const { riskTolerance, totalPricedUsd } = inputs;
  if (!riskTolerance) return null;
  const target = RISK_TARGET_ALLOCATION[riskTolerance];
  if (!target) return null;
  if (totalPricedUsd == null || totalPricedUsd <= 0) return null;
  return {
    cryptoPct: target.cryptoPct,
    stablePct: target.stablePct,
    cryptoUsd: totalPricedUsd * (target.cryptoPct / 100),
    stableUsd: totalPricedUsd * (target.stablePct / 100),
  };
}

export interface AllocationDeltas {
  /** current − target, in USD (positive = overweight vs target). */
  cryptoDeltaUsd: number;
  stableDeltaUsd: number;
  /** current − target, in percentage points (positive = overweight). */
  cryptoDeltaPct: number;
  stableDeltaPct: number;
}

/**
 * Per-bucket difference between the live current allocation and the risk-based
 * target. Positive = current is over the target (overweight); negative = under.
 */
export function deriveAllocationDeltas(inputs: {
  current: { cryptoUsd: number; stableUsd: number; cryptoPct: number; stablePct: number };
  recommended: RecommendedAllocation;
}): AllocationDeltas {
  const { current, recommended } = inputs;
  return {
    cryptoDeltaUsd: current.cryptoUsd - recommended.cryptoUsd,
    stableDeltaUsd: current.stableUsd - recommended.stableUsd,
    cryptoDeltaPct: current.cryptoPct - recommended.cryptoPct,
    stableDeltaPct: current.stablePct - recommended.stablePct,
  };
}
